// Generates the agent installation artifacts shown during host onboarding.
// Pure text generation: nothing here contacts a host or a hub. Generated files
// are English like the product's installation packages.

import type { FileOwner, HostConnection } from "./model";
import { SYSTEM_LABEL } from "./system";
import { isInside } from "./validation";

export const AGENT_PORT = 3552;
export const AGENT_IMAGE = "registry.example.com/docklet/agent:0.33.0";

export interface AgentInstallPlan {
  hostName: string;
  connection: HostConnection;
  /** Direct mode: address the hub connects to. */
  address: string;
  port: number;
  /** Edge mode: internal hub address the agent dials out to (LAN or VPN). */
  hubUrl: string;
  projectDir: string;
  installDir: string;
  /** Manual PUID/PGID; undefined lets the installer read the directory owner. */
  fileOwner?: FileOwner;
  /** Manual socket group; undefined detects it from /var/run/docker.sock. */
  socketGid?: number;
  token: string;
  timeZone: string;
}

export interface InstallArtifacts {
  compose: string;
  env: string;
  script: string;
  readme: string;
  composeCommand: string;
  scriptCommand: string;
}

const q = (v: string) => `'${v.replace(/'/g, "'\\''")}'`;

export function agentCompose(plan: AgentInstallPlan): string {
  const lines = [
    `# Docklet agent for "${plan.hostName}" (${plan.connection} connection).`,
    "# Generated by the Docklet design prototype: demo artifact, the token is a placeholder.",
    "name: docklet-agent",
    "services:",
    "  agent:",
    `    image: \${DOCKLET_AGENT_IMAGE:-${AGENT_IMAGE}}`,
    "    container_name: docklet-agent",
    "    restart: unless-stopped",
    "    env_file: .env",
    "    # Marks Docklet's own agent; stack and container lists skip it by this label, not by name.",
    "    labels:",
    `      ${SYSTEM_LABEL}: "agent"`,
    "    # Docker socket group, independent of the file owner (PUID/PGID).",
    "    group_add:",
    '      - "${DOCKER_SOCKET_GID}"',
  ];
  if (plan.connection === "direct") {
    lines.push("    # The hub connects to this port. Keep it reachable from the hub only.", "    ports:", `      - "${plan.port}:${AGENT_PORT}"`);
  } else {
    lines.push("    # Edge: the agent connects out to the hub; no inbound port is opened.");
  }
  lines.push(
    "    volumes:",
    "      - /var/run/docker.sock:/var/run/docker.sock",
    "      # Project directory: stacks live in <project dir>/<stack>/compose.yaml.",
    `      - ${plan.projectDir}:${plan.projectDir}`,
    "      # Agent state only; never a stack directory.",
    "      - ./data:/data",
    "",
  );
  return lines.join("\n");
}

export function agentEnv(plan: AgentInstallPlan, values: { puid: string; pgid: string; socketGid: string }): string {
  const lines = [
    `# Docklet agent settings for "${plan.hostName}". Demo artifact.`,
    `DOCKLET_MODE=${plan.connection}`,
    plan.connection === "edge" ? `DOCKLET_HUB_URL=${plan.hubUrl}` : `DOCKLET_LISTEN=0.0.0.0:${AGENT_PORT}`,
    `DOCKLET_AGENT_TOKEN=${plan.token}`,
    `DOCKLET_PROJECT_DIR=${plan.projectDir}`,
    "# File owner for project files (PUID/PGID).",
    `PUID=${values.puid}`,
    `PGID=${values.pgid}`,
    "# Group of /var/run/docker.sock.",
    `DOCKER_SOCKET_GID=${values.socketGid}`,
    `TZ=${plan.timeZone}`,
    "",
  ];
  return lines.join("\n");
}

/** .env as written by the shell commands: unknown IDs are read on the host. */
function runtimeEnv(plan: AgentInstallPlan): string {
  return agentEnv(plan, {
    puid: plan.fileOwner ? String(plan.fileOwner.uid) : "${PUID}",
    pgid: plan.fileOwner ? String(plan.fileOwner.gid) : "${PGID}",
    socketGid: plan.socketGid !== undefined ? String(plan.socketGid) : "${DOCKER_SOCKET_GID}",
  });
}

function detectionLines(plan: AgentInstallPlan): string[] {
  const lines: string[] = [];
  if (!plan.fileOwner) {
    lines.push(
      "# File owner proposal: owner of the project directory. Nothing is chown'ed or chmod'ed.",
      `PUID="\${PUID:-$(stat -c %u "$PROJECT_DIR")}"`,
      `PGID="\${PGID:-$(stat -c %g "$PROJECT_DIR")}"`,
    );
  }
  if (plan.socketGid === undefined) lines.push("# Docker socket group, detected separately from the file owner.", 'DOCKER_SOCKET_GID="$(stat -c %g /var/run/docker.sock)"');
  return lines;
}

export function agentScript(plan: AgentInstallPlan): string {
  return [
    "#!/bin/sh",
    `# Docklet agent installer for "${plan.hostName}". Demo artifact from the design prototype.`,
    "set -eu",
    "",
    `INSTALL_DIR=${q(plan.installDir)}`,
    `PROJECT_DIR=${q(plan.projectDir)}`,
    "",
    "# Local checks on this host; the hub cannot see the host before the agent runs.",
    'if [ "$INSTALL_DIR" = "$PROJECT_DIR" ]; then',
    '  echo "The install directory must not be the project directory itself; use a subfolder such as $PROJECT_DIR/docklet-agent." >&2',
    "  exit 1",
    "fi",
    'if [ ! -d "$PROJECT_DIR" ]; then',
    '  echo "Project directory $PROJECT_DIR does not exist. Create it with the intended owner first." >&2',
    "  exit 1",
    "fi",
    'if [ ! -w "$PROJECT_DIR" ]; then',
    '  echo "Warning: $PROJECT_DIR is not writable for the current user; the agent uses PUID/PGID." >&2',
    "fi",
    ...detectionLines(plan),
    'echo "Project directory owner: $(stat -c %U:%G "$PROJECT_DIR") ($(stat -c %u:%g "$PROJECT_DIR"))"',
    "",
    'mkdir -p "$INSTALL_DIR/data"',
    'cd "$INSTALL_DIR"',
    "cat > compose.yaml <<'EOF_COMPOSE'",
    agentCompose(plan).trimEnd(),
    "EOF_COMPOSE",
    "cat > .env <<EOF_ENV",
    runtimeEnv(plan).trimEnd(),
    "EOF_ENV",
    "# Only the agent's own .env holds the token.",
    "chmod 600 .env",
    "docker compose up -d",
    `echo "Docklet agent started in $INSTALL_DIR. After connecting it reports owner, write access and socket group to the hub (Hosts page)."`,
    "",
  ].join("\n");
}

export function agentReadme(plan: AgentInstallPlan): string {
  return [
    `Docklet agent package for "${plan.hostName}"`,
    "",
    "DEMO ARTIFACT from the Docklet design prototype. The token is a placeholder",
    "and the hub address is an example; the package cannot connect anywhere.",
    "",
    `Install directory (agent files only): ${plan.installDir}`,
    `Project directory (stacks):           ${plan.projectDir}`,
    ...(isInside(plan.installDir, plan.projectDir)
      ? ["The agent folder lies inside the project directory. Docklet recognises it by the", `label ${SYSTEM_LABEL}=agent and never lists it as a stack.`]
      : []),
    `Connection: ${plan.connection === "direct" ? `direct, hub connects to port ${plan.port}` : `edge, agent connects to ${plan.hubUrl}`}`,
    "",
    "Files: compose.yaml, .env, install.sh",
    "Run: sh install.sh  (checks locally: project directory exists and is writable,",
    "     reads its owner and the Docker socket group, writes compose.yaml and .env",
    "     into the install directory and starts the agent). Nothing is chown'ed or",
    "     chmod'ed except the agent's own .env (600). The agent reports the result",
    "     to the hub after it connects.",
    "",
  ].join("\n");
}

export function buildInstallArtifacts(plan: AgentInstallPlan): InstallArtifacts {
  const compose = agentCompose(plan);
  const env = agentEnv(plan, {
    puid: plan.fileOwner ? String(plan.fileOwner.uid) : "",
    pgid: plan.fileOwner ? String(plan.fileOwner.gid) : "",
    socketGid: plan.socketGid !== undefined ? String(plan.socketGid) : "",
  });
  const script = agentScript(plan);
  const composeCommand = [
    `INSTALL_DIR=${q(plan.installDir)}`,
    `PROJECT_DIR=${q(plan.projectDir)}`,
    ...detectionLines(plan).filter((l) => !l.startsWith("#")),
    'mkdir -p "$INSTALL_DIR/data" && cd "$INSTALL_DIR"',
    "cat > compose.yaml <<'EOF'",
    compose.trimEnd(),
    "EOF",
    "cat > .env <<EOF",
    runtimeEnv(plan).trimEnd(),
    "EOF",
    "chmod 600 .env && docker compose up -d",
  ].join("\n");
  const scriptCommand = ["cat > /tmp/install-docklet-agent.sh <<'EOF_INSTALLER'", script.trimEnd(), "EOF_INSTALLER", "sh /tmp/install-docklet-agent.sh"].join("\n");
  return { compose, env, script, readme: agentReadme(plan), composeCommand, scriptCommand };
}
